member.example:
An action and its associated builder:

using Kjs.AppLife.Update.Engine.Core;
using Kjs.AppLife.Update.Engine.Core.Design;

[ActionBuilder(typeof(DelayActionBuilder))]
public class DelayAction : UpdateAction {
	private int mSeconds;

	public DelayAction() { }

	public int Seconds {
		get { return this.mSeconds; }
		set { this.mSeconds = value; }
	}

	public override void Execute(UpdateContext context) {
		System.Threading.Thread.Sleep(mSeconds * 1000);
	}

	public override void RollbackExecute(UpdateContext context) { }
}

public class DelayActionBuilder : ActionBuilder {
	public DelayActionBuilder() { }

	private new DelayAction Action {
		get { return (DelayAction)base.Action; }
	}

	protected override void ValidateActionCore(ValidationErrorCollection errors) {
		if(this.Action.Seconds < 0) {
			errors.AddError("Seconds cannot be less than 0.");
		}
	}
}


Imports Kjs.AppLife.Update.Engine.Core
Imports Kjs.AppLife.Update.Engine.Core.Design

<ActionBuilder(GetType(DelayActionBuilder))> _
Public Class DelayAction
	Inherits UpdateAction

	Dim mSeconds As Integer

	Public Sub New()
	End Sub

	Public Property Seconds() As Integer
		Get
			Return mSeconds
		End Get
		Set(ByVal value As Integer)
			mSeconds = value
		End Set
	End Property

	Public Overrides Sub Execute(ByVal context As UpdateContext)
		System.Threading.Thread.Sleep(mSeconds * 1000)
	End Sub

	Public Overrides Sub RollbackExecute(ByVal context As UpdateContext)
	End Sub
End Class

Public Class DelayActionBuilder
	Inherits ActionBuilder

	Public Sub New()
	End Sub

	Public Overloads ReadOnly Property Action() As DelayAction
		Get
			Return CType(MyBase.Action, DelayAction)
		End Get
	End Property

	Protected Overrides Sub ValidateActionCore(ByVal errors As ValidationErrorCollection)
		If Me.Action.Seconds < 0 Then
			errors.AddError("Seconds cannot be less than 0.")
		End If
	End Sub
End Class

The following example demonstrates an implementation of  that uses
the  to edit its action.

public override void StartEditingAction(System.IServiceProvider provider) {
  IWindowsFormsActionEditorService editorService =
    (IWindowsFormsActionEditorService)provider.GetService(typeof(IWindowsFormsActionEditorService));

  if(editorService != null) {
    // MyActionEditorControl has an ActionBuilder property that it uses to call
    // SetActionDirty() and ValidateAction() and to connect to the action that it
    // edits.
    MyActionEditorControl myControl = new MyActionEditorControl();
    myControl.ActionBuilder = this;

    editorService.ShowControl(myControl);
  }
}


Public Overrides Sub StartEditingAction(ByVal provider As System.IServiceProvider)
  Dim editorService As IWindowsFormsActionEditorService = _
   CType(provider.GetService(GetType(IWindowsFormsActionEditorService)), IWindowsFormsActionEditorService)

  If Not (editorService Is Nothing) Then
    ' MyActionEditorControl has an ActionBuilder property that it uses to call
    ' SetActionDirty() and ValidateAction() and to connect to the action that it
    ' edits.
    Dim myControl As New MyActionEditorControl()
    myControl.ActionBuilder = Me

    editorService.ShowControl(myControl)
  End If
End Sub

